===ROUTE invoice.$invoiceId===
import { createFileRoute } from '@tanstack/react-router';
import { LineItemForm } from '../features/lineitems/LineItemForm';
import { LineItemsTable } from '../features/lineitems/LineItemsTable';
import { InvoiceDetail } from '../slots/defs/invoiceDetail';

// An invoice's detail page: one new file under routes/ (CLAUDE.md rule 1). Opening an invoice is a
// route, not a flag on the list (rule 2) — the router decides what renders, so the project's invoice
// table is left behind and only the invoice's own detail shows. The page composes the line-item form
// + list; each queries/mutates for itself under the ['lineitems', invoiceId] key.
export const Route = createFileRoute('/invoice/$invoiceId')({
  component: InvoiceDetailPage,
});

function InvoiceDetailPage() {
  const { invoiceId } = Route.useParams();
  const id = Number(invoiceId);
  return (
    <section data-testid="invoice-detail">
      <LineItemForm invoiceId={id} />
      <LineItemsTable invoiceId={id} />
      <InvoiceDetail.Slot invoiceId={id} />
    </section>
  );
}
===invoiceDetail def===
import { defineSlot } from '../Slot';

/**
 * The body of an invoice's detail page — the region where per-invoice panels live (the payments
 * list, and anything added later). Declared once here; features fill it without the page listing
 * what goes in it (CLAUDE.md rule 3). Its context is the invoice's id.
 */
export const InvoiceDetail = defineSlot<{ invoiceId: number }>('invoice.detail');
===due-amount slot===
import { useQuery } from '@tanstack/react-query';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { invoicesKey, fetchInvoices, type Invoice } from './queries';
import { formatMoney } from '../../ui/money';

// The "still due after payments" cell on every invoice row — its own file filling the invoice.row
// region (CLAUDE.md rule 3). The amount due (invoice amount minus its payments) is derived
// server-side and carried on each invoice, so this cell reads the SAME ['invoices', projectId]
// query the table already loaded (rule 5) and finds its own invoice — no parent hands it the value,
// and a payment write that invalidates the key refreshes this cell for free. Renders under
// data-testid="invoice-due-amount" (the test contract).
export const contribution = InvoiceRow.fill({
  order: 15,
  Component: ({ invoiceId, projectId }: { invoiceId: number; projectId: number; status: string }) => {
    const { data: invoices } = useQuery({
      queryKey: invoicesKey(projectId),
      queryFn: () => fetchInvoices(projectId),
    });
    const invoice = invoices?.find((row: Invoice) => row.id === invoiceId);
    if (!invoice) {
      return null;
    }
    return <td data-testid="invoice-due-amount">{formatMoney(invoice.due)}</td>;
  },
});

