===invoices open.slot===
import { Link } from '@tanstack/react-router';
import { InvoiceRow } from '../../slots/defs/invoiceRow';

// The "open this invoice" action on every invoice row — its own file filling the invoice.row region
// (CLAUDE.md rule 3). Drilling in is a route (rule 2): the link navigates to /invoice/$invoiceId,
// where the invoice's line items live. Carries data-testid="invoice-open-<id>" (the test contract).
export const contribution = InvoiceRow.fill({
  order: 0,
  Component: ({ invoiceId }: { invoiceId: number; projectId: number; status: string }) => (
    <td>
      <Link
        to="/invoice/$invoiceId"
        params={{ invoiceId: String(invoiceId) }}
        data-testid={`invoice-open-${invoiceId}`}
      >
        Open
      </Link>
    </td>
  ),
});
===lineitems queries===
import { getJson, postJson } from '../../api/http';

// An invoice's line items under a per-invoice key: anything showing invoice 1's lines reads
// ['lineitems', 1], and a write invalidates the same key to refresh them (CLAUDE.md rule 5). A line
// carries what is being charged for (description), how many (qty), the unit that quantity is measured
// in (unit, e.g. "hours") and the price each (unitPrice).
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unit: string;
  unitPrice: number;
};

export const lineItemsKey = (invoiceId: number) => ['lineitems', invoiceId] as const;

export function fetchLineItems(invoiceId: number): Promise<LineItem[]> {
  return getJson<LineItem[]>(`/api/invoices/${invoiceId}/lineitems`);
}

/** Add a line to an invoice; the invoice id is in the path, the rest is the body (CLAUDE.md server). */
export function createLineItem(
  invoiceId: number,
  input: { description: string; qty: number; unit: string; unitPrice: number },
): Promise<LineItem> {
  return postJson<LineItem>(`/api/invoices/${invoiceId}/lineitems`, input);
}

/** Change a line on an invoice; ids are in the path, the new values are the body. */
export function updateLineItem(
  invoiceId: number,
  lineItemId: number,
  input: { description: string; qty: number; unitPrice: number },
): Promise<LineItem> {
  return postJson<LineItem>(`/api/invoices/${invoiceId}/lineitems/${lineItemId}`, input);
}

